const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class Narrator{
 constructor(){this.voice=null;this.last='';this.unlocked=false;this.audio=null;this.preloads=new Map();this.synth=globalThis.window?.speechSynthesis;this.Utterance=globalThis.window?.SpeechSynthesisUtterance;}
 get available(){return !!globalThis.window?.Audio||!!(this.synth&&this.Utterance);}
 stop(){this.synth?.cancel();if(this.audio){this.audio.pause();this.audio.currentTime=0;this.audio=null;}this.last='';}
 preload(clips=[]){if(!globalThis.window?.Audio)return;const known=/^(acquired|story-[0-2]|equipment-[0-3]|scout-[0-1])$/;for(const clip of clips){if(!known.test(clip)||this.preloads.has(clip))continue;const audio=new window.Audio('./assets/narration/'+clip+'.wav');audio.preload='auto';audio.load?.();this.preloads.set(clip,audio);}}
 read(text,{enabled=true,volume=.65,force=false,clip=null}={}){if(!enabled||!this.available||!this.unlocked)return;if(text===this.last&&!force)return;this.stop();this.last=text;if(clip){const match=clip.match(/^(.*-)(\d+)$/);if(match)this.preload([match[1]+(Number(match[2])+1)]);}const speech=()=>{if(!this.synth||!this.Utterance||this.last!==text)return;const u=new this.Utterance(text);const voices=this.synth.getVoices();u.voice=voices.find(v=>v.localService&&/^en-US/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang))||null;u.lang='en-US';u.rate=.92;u.pitch=.88;u.volume=Math.max(0,Math.min(1,volume));this.synth.speak(u);};if(clip&&globalThis.window?.Audio){const cached=this.preloads.get(clip),audio=this.audio=cached?.cloneNode?.()||new window.Audio('./assets/narration/'+clip+'.wav');audio.volume=Math.max(0,Math.min(1,volume));audio.play().catch(speech);}else speech();}

}
export const EQUIPMENT_LESSONS=[
 {target:'bike',label:'01 / MOTORCYCLE',title:'Your way through the quiet.',text:'The bike turns battery charge into distance. Ride with motor assist, or pedal when energy is low. Your stamina recovers when you ease off. Every drone returns to this motorcycle.',detail:'W / S · accelerate and brake. P · pedal. F · mount or dismount.'},
 {target:'trailer',label:'02 / TRAILER RESERVE',title:'Carry tomorrow’s charge.',text:'The trailer holds a separate reserve battery. Reserve to bike transfers stored energy into the motorcycle. Keep it attached to use that transfer. The reserve gauge shows what remains.',detail:'T · transfer reserve. Equipment → Bike / Trailer shows both batteries.'},
 {target:'trailer',label:'03 / GENERATION',title:'Park. Unfold. Replenish.',text:'Stop before generating power. Solar unfolds the panels and charges in daylight. Fuel uses the finite fuel in your tank. Stowed turns generation off. Resume the game for charging to run.',detail:'Water power unlocks at the Spillway. Full storage stops fuel consumption.'},
 {target:'trailer',label:'04 / CARGO & HITCH',title:'A workshop on two wheels.',text:'The trailer stores sixty kilograms of cargo and carries your drone fleet. Open the pack near it to move supplies. Detach parks it behind; approach within eight meters to reattach. Heavy cargo costs more riding energy.',detail:'Open Bike / Trailer any time to replay this guide and inspect each control.'}
];
export const SCOUT_LESSONS=[
 {target:'scout',label:'SCOUT-01 / ACQUIRED',title:'Your eyes beyond the road.',text:'Scout recovered and linked to your fleet. The first salvage box supplied its field kit, wire and cells. The aircraft is ready at your trailer. You can now launch it from the motorcycle.',detail:'Q launches. The cyan beacon makes it visible from the ground.'},
 {target:'scout',label:'SCOUT-01 / FLIGHT',title:'Climb. Look. Come home.',text:'Use movement controls to fly, and rise or descend to change altitude. Scan nearby contacts, then recall the scout. Amber means it is coming home. Wait until it docks before talking to Mara.',detail:'SPACE / SHIFT · rise / descend. R · scan. Q · recall. H · camera. B · sensors. L · light.'}
];
export function lessonPanel(lesson,index,count,narration=true){return `<article class="equipmentLesson"><div class="lessonProgress">${Array.from({length:count},(_,i)=>`<i class="${i<=index?'read':''}"></i>`).join('')}</div><span class="eyebrow">${lesson.label}</span><h2>${lesson.title}</h2><p class="lessonText">${lesson.text}</p><aside>${lesson.detail}</aside><div class="lessonActions"><button data-tutorial="mute" aria-pressed="${narration}">${narration?'MUTE NARRATOR':'NARRATOR OFF'}</button><button data-tutorial="skip">SKIP TUTORIAL</button></div><div class="lessonNavigation"><button data-brief="back" ${index?'':'disabled'}>← BACK</button><button class="primary" data-brief="next">${index===count-1?'CONTINUE →':'NEXT →'}</button></div></article>`;}
export const RIG_FEATURES={reserve:['Reserve → bike','Moves up to 10 reserve units into the motorcycle. Requires an attached trailer, available reserve and room in the bike battery. T performs the same transfer.'],generator:['Solar / Fuel / Stowed','Solar unfolds the panels and needs daylight. Fuel consumes your finite tank. Both work only while stopped and unpaused. Stowed stops generation. Water is unlocked at the Spillway.'],cargo:['Cargo storage','Stand within 8 m of the trailer and open Pack. Select Trailer storage to move items. It holds 60 kg; its contents persist when parked.'],hitch:['Attach / Detach','Stop before unhitching. Return within 8 m to attach it again. A parked trailer keeps its cargo and generation settings.'],drone:['Bike → drone','Spends 10% bike charge to restore up to 50% charge to the selected drone. Open Fleet to select a different aircraft or give separate flight commands.']};
export function rigGuide(feature='reserve'){const [title,text]=RIG_FEATURES[feature]||RIG_FEATURES.reserve;return `<section class="rigGuide"><div class="rigDrawing"><svg viewBox="0 0 640 250" role="img" aria-label="Trailer: solar panels above the reserve battery and cargo bay; hitch at the front; drone dock above"><defs><linearGradient id="rigMetal" x2="0" y2="1"><stop stop-color="#516762"/><stop offset="1" stop-color="#182c32"/></linearGradient></defs><path d="M54 187h118m-85-9v18" stroke="#b5b7a1" stroke-width="8"/><path d="M176 98h321v103H176z" fill="url(#rigMetal)" stroke="#91b9b1"/><path d="M209 126h88v51h-88zm110 0h148v51H319" fill="#11232a" stroke="#bbcbab"/><path d="M157 75l62-49h260l51 49z" fill="#264954" stroke="#7aa9b5"/><path d="M214 30l-29 40m93-40l-12 40m73-40v40m65-40l12 40m59-40l27 40M194 52h314" stroke="#7096aa"/><circle cx="234" cy="204" r="28" fill="#10181b" stroke="#819996" stroke-width="7"/><circle cx="446" cy="204" r="28" fill="#10181b" stroke="#819996" stroke-width="7"/><g fill="#e3d4a7" font-size="11" font-family="monospace"><text x="252" y="17">SOLAR ARRAY</text><text x="220" y="155">RESERVE</text><text x="360" y="155">CARGO</text><text x="30" y="165">HITCH</text><text x="500" y="119">GENERATOR</text></g></svg></div><div class="rigFeatureTabs">${Object.entries(RIG_FEATURES).map(([id,[name]])=>`<button data-rig-focus="${id}" aria-pressed="${feature===id}">${name}</button>`).join('')}</div><div class="rigExplanation"><h3>${title}</h3><p>${text}</p><button data-tutorial="trailer">REPLAY TRAILER WALKTHROUGH</button></div></section>`;}
export function characterPortrait(name,color='#9ca78b'){const female=/Mara|June|Ada/i.test(name);return `<div class="contactPortrait" style="--coat:${color}"><svg viewBox="0 0 240 300" role="img" aria-label="${esc(name)} field portrait"><path fill="#17282b" d="M0 0h240v300H0z"/><path d="M10 260L230 40M-20 180L180-20M70 320L270 120" stroke="#45605b" stroke-width="1"/><circle cx="120" cy="112" r="75" fill="#354842"/><path d="M28 300v-53q10-63 69-65h46q61 2 69 65v53" fill="var(--coat)"/><path d="M95 178h50v44l-25 25-25-25" fill="#a48a70"/><path d="M76 82q4-40 44-41t44 41v59q-8 49-44 51-36-2-44-51" fill="#c2a78a"/><path d="M72 113V71q8-43 48-43t50 43v${female?'115l-20-13V77l-16-16-39 25-9 89-18 14':'42l-17-35-61 5'}z" fill="#494439"/><path d="M89 120h21m20 0h21" stroke="#3c4038" stroke-width="4"/><path d="M117 126l-4 22h13m-20 15q14 8 29-1" fill="none" stroke="#84634f" stroke-width="3"/><path d="M59 219l39-22 22 50 23-50 41 22-13 81H69z" fill="#263d3c"/><path d="M66 238h37v43H66zm71 0h37v43h-37" fill="var(--coat)" stroke="#b0ad88"/><path d="M120 251v49" stroke="#c9b789"/><rect x="158" y="214" width="13" height="24" rx="2" fill="#77c5b5"/></svg><span>${esc(name.toUpperCase())}</span></div>`;}
